Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
Local Ltac transport_after_call segs m m' MU WM ::= transport_after_call_fast segs m m' MU WM.
Local Ltac lia ::= lia3.

Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Ltac zs := zstep; try (fix_litstore; mem_after_store_opt).
Ltac fix_ret := lazymatch goal with |- evt _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?n)) _ _ _ _) =>
  replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]) end.

Lemma rw_cells_recast : forall m A cs cs', rw_cells rsegs m A cs -> cells_wf cs' -> cells_bytes cs' = cells_bytes cs -> rw_cells rsegs m A cs'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0|30;!1+0!1,10!1+4+5!4'9'7#5#4#3!1+41!1'=#6!1'?#<!1'<#<!1'?#=$n;R+D!4':'7#@#?!1';#1$m;R%~R!1+0!1,1|600;!1+21$A;R+3$cs;R2$cs';R2$H;R!4'6'7#4#3#2!5'83!4':'7#5#4!1';!1'<#3%~R!1'=#2%~R!3+>4!1'?#3!1'?#4!4'6'7#7#6#4$~R3$~R!4':'7#6#5!1';!1'<#4!2$H;R!4'9'7#7#6#5!5'85!4'@'7#8#7!1'?#6%~R!4':'7#8#7!1';!1'<#6%~R!1'=#6%~R!3+>4!1'?#7!1'?#8!4'6'7#;#:#8$~R5$~R!4'@'7#9#8!1'?#7!2$W;R!1'=#8$B;R!4'@'7#;#:!1'?#9$R;R!4':'7#<#;!1';!1'<#:$W';R!1'=#:$E;R!3+>4!1'?#;6!4,A!4'9'7#?#>#<!4':'7#?#>!1';7!4,A!1'=#<!4'@'7#?#>6#2!6'B48$l;R4!4'@'7#@#?#1#46#1!6'C+D!2'E169!6'B48$l;R4!4':'7#@#?!1';!2'E1#1!6'B+D!1'<#=9#3!2'E18!2'F#=#56#17!2'F#<#2#2#1#1#2#1#1").
Qed.

